    "facts": {
      "de": [ "Haushaltsgeräte." ],
      "hu": [ "Háztartási gépek." ],
      "ro": [ "Electrocasnice." ],
      "en": [ "Household appliances." ]
    },
    "descriptionAdvanced": {
      "de": "Găești ist eine dynamische Industriestadt im Westen des Kreises Dâmbovița, die landesweit als Zentrum für die Herstellung von Haushaltsgeräten bekannt ist. Die Stadt beherbergt eine der größten Kühlschrankfabriken Europas, was ihr eine stabile wirtschaftliche Basis und überregionale Bedeutung verleiht. Geografisch liegt Găești in einer fruchtbaren Ebene am Rande der Getischen Hochebene, was die Stadt zu einem wichtigen Bindeglied zwischen der Walachischen Tiefebene und den Karpatenvorbergen macht. Die Geschichte von Găești ist eng mit dem Adelshaus Olănescu verbunden, deren ehemaliges Anwesen einst das kulturelle Leben prägte. Trotz ihres industriellen Fokus hat die Stadt in den letzten Jahren viel in die städtische Infrastruktur und Grünanlagen investiert. Kulturell ist Găești stolz auf seine Traditionen und das lokale Kulturhaus, das ein wichtiger Treffpunkt für die Gemeinschaft ist. Die strategische Lage an der Autobahn A1 macht Găești zudem zu einem attraktiven Standort für moderne Logistikunternehmen.",
      "hu": "",
      "ro": "Găești este un oraș industrial din județul Dâmbovița, cunoscut la nivel național și european ca fiind centrul producției de aparate frigorifice din România. Aici se află fabrica Arctic, cel mai mare producător de electrocasnice din țară și unul dintre cei mai importanți din Europa. Dezvoltarea orașului este strâns legată de această platformă industrială, care a asigurat prosperitatea și modernizarea localității. Situat strategic în Câmpia Română, pe Autostrada A1, Găești este și un important nod logistic. Orașul este locul de naștere al marelui naist Gheorghe Zamfir, personalitate care a adus faimă României în întreaga lume. În ciuda profilului său industrial, Găești oferă parcuri îngrijite și o viață culturală activă, fiind un exemplu de centru urban dinamic din sudul țării.",
      "en": ""
    },
    "factsAdvanced": {
      "de": ["In Găești befindet sich das riesige Arctic-Werk, der größte Kühlschrankproduzent in Kontinentaleuropa.", "Die Stadt wurde erstmals im Jahr 1498 in einem Dokument von Radu cel Mare erwähnt.", "Găești liegt strategisch günstig an der Hauptverkehrsader A1 zwischen Bukarest und Pitești.", "Die Stadt war im 19. Jahrhundert ein wichtiger Marktplatz für landwirtschaftliche Produkte.", "Der Name der Stadt leitet sich vermutlich von der Adelsfamilie Găești ab.", "In der Stadt gibt es ein bedeutendes Denkmal für den Panflötenspieler Gheorghe Zamfir, der hier geboren wurde.", "Găești liegt am Fluss Potop, in einer Region mit intensivem Gartenbau.", "Die Stadt hat sich in den letzten Jahrzehnten zu einem modernen urbanen Zentrum entwickelt."],
      "hu": [],
      "ro": ["Fabrica Arctic de la Găești, înființată în 1970, este cea mai mare fabrică de frigidere din Europa continentală.", "Găești este locul de naștere al celebrului naist Gheorghe Zamfir (n. 1941).", "Prima atestare documentară a orașului datează din anul 1498.", "Orașul este situat la o distanță de 70 km de București și 30 km de Pitești.", "Găești a fost reședința istorică a Plasei Găești în perioada interbelică.", "Stema orașului include o frunză de tei și un arc, simbolizând pădurile și vechile tradiții de vânătoare."],
      "en": []
    }
